"use client";

import * as React from "react";
import { MODAL_ROOT, SCRIM, useModal } from "./modal";
import {
  EASE_OUT,
  INTERACTION_FOCUS,
  INTERACTION_PRESS,
  useInteractionReducedMotion,
} from "./imported-ui-interaction-motion";

/* ─────────────────────────────────────────────────────────
 * DIALOG: a decision that needs the whole screen
 *
 *   open     the page fades back under a veil of its own
 *            background (no blur); the panel rises 8px, out of a
 *            4px blur, from 0.96
 *   close    Escape, the ✕ or a press on the veil; it sinks back
 *            the way it came and focus returns to what opened it
 *   long     the body scrolls inside the panel; the page behind
 *            never moves
 *
 * The native <dialog>: focus stays inside, the page is inert,
 * and it sits above everything without z-index games.
 * ───────────────────────────────────────────────────────── */

export interface DialogProps {
  open?: boolean;
  defaultOpen?: boolean;
  onOpenChange?: (open: boolean) => void;
  /** A button that opens it. */
  trigger?: React.ReactElement<React.HTMLAttributes<HTMLElement>>;
  title: React.ReactNode;
  description?: React.ReactNode;
  /** The body, or a function that gets `close`. */
  children?:
    React.ReactNode | ((api: { close: () => void }) => React.ReactNode);
  /** Buttons along the bottom, or a function that gets `close`. */
  footer?: React.ReactNode | ((api: { close: () => void }) => React.ReactNode);
  /** 400, 520 or 680px wide. */
  size?: "sm" | "md" | "lg";
  /** Press on the veil closes it. Turn off for forms that would lose work. */
  dismissible?: boolean;
  className?: string;
}

const WIDTH = { sm: 400, md: 520, lg: 680 };

export function Dialog({
  open: controlled,
  defaultOpen = false,
  onOpenChange,
  trigger,
  title,
  description,
  children,
  footer,
  size = "md",
  dismissible = true,
  className = "",
}: DialogProps) {
  const reduced = useInteractionReducedMotion();
  const [own, setOwn] = React.useState(defaultOpen);
  const open = controlled ?? own;
  const setOpen = (next: boolean) => {
    if (controlled === undefined) setOwn(next);
    onOpenChange?.(next);
  };
  const close = () => setOpen(false);
  const { dialog, mounted, shown } = useModal(open, close, 220);
  const titleId = React.useId();
  const descId = React.useId();
  const ease = EASE_OUT;

  return (
    <>
      {trigger &&
        React.cloneElement(trigger, {
          "aria-haspopup": "dialog",
          onClick: (e: React.MouseEvent<HTMLElement>) => {
            trigger.props.onClick?.(e);
            setOpen(true);
          },
        })}
      {mounted && (
        <dialog
          ref={dialog}
          aria-labelledby={titleId}
          aria-describedby={description ? descId : undefined}
          className={MODAL_ROOT}
        >
          <div
            className={SCRIM}
            onClick={() => dismissible && close()}
            style={{
              opacity: shown ? 1 : 0,
              transition: `opacity ${shown ? 260 : 200}ms ${ease}`,
            }}
          />
          <div className="pointer-events-none absolute inset-0 flex items-end justify-center p-3 sm:items-center sm:p-6">
            <div
              data-modal-panel=""
              tabIndex={-1}
              className={`pointer-events-auto relative flex max-h-[min(85dvh,760px)] w-full flex-col rounded-[22px] bg-background shadow-[0_0_0_1px_var(--border)] outline-none ${className}`}
              style={{
                maxWidth: WIDTH[size],
                opacity: shown ? 1 : 0,
                translate: shown || reduced ? "0 0" : "0 8px",
                scale: shown || reduced ? "1" : "0.96",
                filter: shown || reduced ? "blur(0px)" : "blur(4px)",
                transition: reduced
                  ? "opacity 160ms ease-out"
                  : shown
                    ? `opacity 240ms ${ease}, translate 420ms ${ease}, scale 420ms ${ease}, filter 240ms ${ease}`
                    : `opacity 180ms ${ease}, translate 220ms ${ease}, scale 220ms ${ease}, filter 180ms ${ease}`,
              }}
            >
              <div className="flex items-start gap-4 px-6 pb-2 pt-5">
                <div className="flex min-w-0 flex-1 flex-col gap-1">
                  <h2
                    id={titleId}
                    className="text-[16px] font-semibold tracking-[-0.01em] text-foreground"
                  >
                    {title}
                  </h2>
                  {description && (
                    <p
                      id={descId}
                      className="text-[13.5px] leading-relaxed text-muted-foreground"
                    >
                      {description}
                    </p>
                  )}
                </div>
                <button
                  type="button"
                  aria-label="Close"
                  onClick={close}
                  className={`-mr-2 flex size-8 shrink-0 items-center justify-center rounded-full text-muted-foreground cursor-pointer hover:bg-accent hover:text-foreground ${INTERACTION_PRESS} ${INTERACTION_FOCUS}`}
                >
                  <svg viewBox="0 0 16 16" fill="none" className="size-3.5">
                    <path
                      d="M4 4l8 8M12 4l-8 8"
                      stroke="currentColor"
                      strokeWidth="1.6"
                      strokeLinecap="round"
                    />
                  </svg>
                </button>
              </div>
              {children !== undefined && (
                <div className="min-h-0 flex-1 overflow-y-auto overscroll-contain px-6 py-2 text-[13.5px] leading-relaxed text-foreground">
                  {typeof children === "function"
                    ? children({ close })
                    : children}
                </div>
              )}
              {footer !== undefined && (
                <div className="flex flex-col-reverse gap-2 px-6 pb-5 pt-4 sm:flex-row sm:justify-end">
                  {typeof footer === "function" ? footer({ close }) : footer}
                </div>
              )}
              {footer === undefined && <div className="h-4" />}
            </div>
          </div>
        </dialog>
      )}
    </>
  );
}

export default Dialog;

"use client";

import * as React from "react";

/* ─────────────────────────────────────────────────────────
 * MODAL: the native <dialog> under Dialog and Sheet
 *
 *   open     showModal() (focus trap, inert page, top layer) and
 *            the next frame turns `shown` on for the entry motion
 *   close    Escape and the scrim ask to close; the surface plays
 *            its exit, then dialog.close() and focus goes back to
 *            whatever opened it
 *   scroll   wheel and touch scrolling outside a scrollable part
 *            of the panel are stopped at the dialog, so the page
 *            behind never moves (the page's own styles are never
 *            touched: no layout shift, no restyle of <html>)
 * ───────────────────────────────────────────────────────── */

export function useModal(open: boolean, onClose: () => void, exit = 220) {
  const dialog = React.useRef<HTMLDialogElement>(null);
  const [mounted, setMounted] = React.useState(open);
  const [shown, setShown] = React.useState(false);
  const opener = React.useRef<HTMLElement | null>(null);
  const close = React.useRef(onClose);
  React.useEffect(() => {
    close.current = onClose;
  });
  if (open && !mounted) setMounted(true);

  React.useEffect(() => {
    const el = dialog.current;
    if (!el) return;
    if (open) {
      opener.current = document.activeElement as HTMLElement | null;
      if (!el.open) el.showModal();
      // Start on the panel, not its first control: no keyboard popping up on phones, no
      // slider bubble or tooltip showing uninvited.
      el.querySelector<HTMLElement>("[data-modal-panel]")?.focus({
        preventScroll: true,
      });
      let inner = 0;
      const outer = requestAnimationFrame(() => {
        inner = requestAnimationFrame(() => setShown(true));
      });
      return () => {
        cancelAnimationFrame(outer);
        cancelAnimationFrame(inner);
      };
    }
    const timer = window.setTimeout(() => {
      if (el.open) el.close();
      setMounted(false);
      setShown(false);
      opener.current?.focus?.({ preventScroll: true });
    }, exit);
    return () => window.clearTimeout(timer);
  }, [open, mounted, exit]);

  React.useEffect(() => {
    const el = dialog.current;
    if (!el || !mounted) return;
    const onCancel = (e: Event) => {
      e.preventDefault();
      close.current();
    };
    // Stop scrolling from leaking to the page unless it happens inside something that scrolls.
    const guard = (e: Event) => {
      let node = e.target as HTMLElement | null;
      while (node && node !== el) {
        const style = getComputedStyle(node);
        if (
          /(auto|scroll)/.test(style.overflowY) &&
          node.scrollHeight > node.clientHeight
        )
          return;
        node = node.parentElement;
      }
      e.preventDefault();
    };
    el.addEventListener("cancel", onCancel);
    el.addEventListener("wheel", guard, { passive: false });
    el.addEventListener("touchmove", guard, { passive: false });
    return () => {
      el.removeEventListener("cancel", onCancel);
      el.removeEventListener("wheel", guard);
      el.removeEventListener("touchmove", guard);
    };
  }, [mounted]);

  return { dialog, mounted: mounted || open, shown: open && shown };
}

/** Class for the full-window <dialog> both surfaces sit in. */
export const MODAL_ROOT =
  // overflow: clip, never hidden: hidden can still be scrolled, and focusing something inside
  // the off-screen panel scrolled the dialog mid-slide (the sheet's jerk on opening).
  "fixed inset-0 m-0 h-dvh max-h-none w-screen max-w-none overflow-clip bg-transparent p-0 text-foreground outline-none backdrop:bg-transparent";

/** The dim behind the surface: the page fades back under a veil of the background colour, no blur. */
export const SCRIM =
  "absolute inset-0 bg-[color-mix(in_oklab,var(--background)_62%,transparent)]";

"use client";

import * as React from "react";

export const EASE_OUT = "cubic-bezier(0.16, 1, 0.3, 1)";
export const EASE_SETTLE = "cubic-bezier(0.22, 1.18, 0.36, 1)";
/** Thrown things (indicators, thumbs): a slight overshoot on transform only. */
export const EASE_THROW = "cubic-bezier(0.34, 1.36, 0.64, 1)";
/**
 * The press every button primitive shares: a 3% give that eases in and settles back.
 * Tailwind v4's scale-* writes the `scale` property, so `scale` has to be in the list
 * or the press snaps.
 */
export const INTERACTION_PRESS =
  "transition-[background-color,color,box-shadow,opacity,scale] duration-200 ease-[cubic-bezier(0.16,1,0.3,1)] active:scale-[0.97] motion-reduce:transition-none motion-reduce:active:scale-100";
export const INTERACTION_FOCUS =
  "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring/50 focus-visible:ring-offset-2 focus-visible:ring-offset-background";

const query = "(prefers-reduced-motion: reduce)";
const subscribe = (notify: () => void) => {
  const media = window.matchMedia(query);
  media.addEventListener("change", notify);
  return () => media.removeEventListener("change", notify);
};
export const useInteractionReducedMotion = () =>
  React.useSyncExternalStore(
    subscribe,
    () => window.matchMedia(query).matches,
    () => false,
  );

export function useInteractionActivity<T extends Element>() {
  const ref = React.useRef<T>(null);
  const [visible, setVisible] = React.useState(false);
  const [hidden, setHidden] = React.useState(false);
  React.useEffect(() => {
    const el = ref.current;
    if (!el) return;
    const observer = new IntersectionObserver(([entry]) =>
      setVisible(entry.isIntersecting),
    );
    observer.observe(el);
    const visibility = () => setHidden(document.hidden);
    visibility();
    document.addEventListener("visibilitychange", visibility);
    return () => {
      observer.disconnect();
      document.removeEventListener("visibilitychange", visibility);
    };
  }, []);
  return { ref, active: visible && !hidden };
}

export function interactionIcon(
  on: boolean,
  reduced: boolean,
): React.CSSProperties {
  return {
    opacity: on ? 1 : 0,
    transform: on ? "none" : "scale(0.6)",
    filter: on ? "blur(0px)" : "blur(3px)",
    transition: reduced
      ? "none"
      : `opacity 220ms ${EASE_OUT}, transform 380ms ${EASE_OUT}, filter 220ms ${EASE_OUT}`,
  };
}

/** Sample recent movement rather than averaging a long drag and losing its release velocity. */
export type PointerSample = { x: number; time: number };
export function samplePointer(
  samples: PointerSample[],
  x: number,
  time: number,
) {
  samples.push({ x, time });
  while (samples.length > 2 && time - samples[0].time > 100) samples.shift();
}
export function releaseVelocity(samples: PointerSample[], now: number) {
  if (samples.length < 2 || now - samples[samples.length - 1].time > 100)
    return 0;
  const first = samples[0],
    last = samples[samples.length - 1];
  return (last.x - first.x) / Math.max(1, last.time - first.time);
}

/** Smooth Apple/rational rubber-band curve: continuous exponential-like resistance without linear kinks. */
export function rubberBand(
  overshoot: number,
  dimension = 320,
  constant = 0.55,
): number {
  const d = dimension || 320;
  const abs = Math.abs(overshoot);
  return Math.sign(overshoot) * (1 - 1 / ((abs * constant) / d + 1)) * d;
}

/** Projects resting travel from release velocity (velocity in px/ms; time in seconds). */
export function projectInertia(
  distance: number,
  velocity: number,
  time = 0.12,
): number {
  return distance + velocity * 1000 * time;
}

/** Smooths incoming release velocity toward a boundary so springs don't slam or clip into walls. */
export function softenVelocity(
  velocity: number,
  distanceToTarget: number,
  factor = 10,
): number {
  const maxAllowed = Math.abs(distanceToTarget) * factor;
  return Math.sign(velocity) * Math.min(Math.abs(velocity), maxAllowed);
}

/** A damped spring sampled by WAAPI: tuned for organic lightness with a hint of life (3% breath). */
export function springFrames(
  from: number,
  to: number,
  velocity = 0,
  duration = 480,
  config: { omega?: number; damping?: number; steps?: number } = {},
) {
  const { omega = 16, damping = 0.74, steps = 36 } = config;
  const damped = omega * Math.sqrt(Math.max(0.001, 1 - damping * damping));
  const displacement = from - to;
  const coefficient =
    (velocity * 1000 + damping * omega * displacement) / damped;
  return Array.from({ length: steps + 1 }, (_, i) => {
    const t = (i / steps) * (duration / 1000);
    const value =
      to +
      Math.exp(-damping * omega * t) *
        (displacement * Math.cos(damped * t) +
          coefficient * Math.sin(damped * t));
    return { value: i === steps ? to : value, offset: i / steps };
  });
}

